import{_ as t,o as a,c as o,a2 as n}from"./chunks/framework.vLhlLNVn.js";const s="/assets/einrichten.DLQPpRAI.png",q=JSON.parse('{"title":"Installation and requirements","description":"","frontmatter":{"order":1,"adapter":"sourceanalytix","editLink":"https://github.com/DrozmotiX/ioBroker.sourceanalytix/edit/main/docs/en/01.erste-schritte/01.installation.md"},"headers":[],"relativePath":"adapter/sourceanalytix/erste-schritte/installation.md","filePath":"adapter/sourceanalytix/erste-schritte/installation.md","lastUpdated":null}'),r={name:"adapter/sourceanalytix/erste-schritte/installation.md"};function i(l,e,d,u,c,h){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="installation-and-requirements" tabindex="-1">Installation and requirements <a class="header-anchor" href="#installation-and-requirements" aria-label="Permalink to &quot;Installation and requirements&quot;">​</a></h1><p><a id="requirements-sourceanalytix-have-node-js"></a></p><h2 id="what-does-sourceanalytix-require-node-js-js-controller-admin" tabindex="-1">What does SourceAnalytix require (Node.js, js-controller, Admin)? <a class="header-anchor" href="#what-does-sourceanalytix-require-node-js-js-controller-admin" aria-label="Permalink to &quot;What does SourceAnalytix require (Node.js, js-controller, Admin)?&quot;">​</a></h2><p><strong>In short:</strong> From v0.7.0, SourceAnalytix needs Node.js 22, js-controller 6.0.11 and Admin 8.0.0 or newer. Admin 8 is required because the instance settings page, with its &quot;Overview&quot; and &quot;Problems&quot; tabs, is built from Admin 8 components.</p><table tabindex="0"><thead><tr><th></th><th>from v0.7.0</th><th>v0.6.0 to v0.6.x</th></tr></thead><tbody><tr><td>Node.js</td><td>22 or newer</td><td>22 or newer</td></tr><tr><td>js-controller</td><td>6.0.11 or newer</td><td>6.0.11 or newer</td></tr><tr><td>Admin</td><td>8.0.0 or newer</td><td>7.8.23 or newer</td></tr></tbody></table><p>Check the versions in the console with <code>iobroker -v</code> (js-controller) and <code>node -v</code> (Node.js). If your system doesn&#39;t meet a requirement, update that component first and then SourceAnalytix. v0.6.0 to v0.6.x work with Admin 7.8 and with Admin 8. Older statements from the forum such as &quot;works with Admin 6&quot; no longer apply.</p><h3 id="if-sourceanalytix-doesn-t-start-after-a-node-js-update" tabindex="-1">If SourceAnalytix doesn&#39;t start after a Node.js update <a class="header-anchor" href="#if-sourceanalytix-doesn-t-start-after-a-node-js-update" aria-label="Permalink to &quot;If SourceAnalytix doesn&#39;t start after a Node.js update&quot;">​</a></h3><p>If the log shows <code>TypeError: Class extends value … is not a constructor or null</code> after a Node.js update, the js-controller is usually too old. Update the js-controller, run <code>iob fix</code> in the console and restart the instance. If ioBroker runs in Docker, update the container image instead and restore your backup if necessary.</p><p><strong>See also:</strong> <a href="./../anleitungen/betrieb-und-wartung#update-sourceanalytix-downgrade">How do I update SourceAnalytix (and what is a downgrade)?</a> · <a href="./../fehlerbehebung/log-meldungen#installation-admin-display-problems">Problems with installation and the Admin display</a></p><p><a id="install-sourceanalytix-create-instance"></a></p><h2 id="how-do-i-install-sourceanalytix-and-create-an-instance" tabindex="-1">How do I install SourceAnalytix and create an instance? <a class="header-anchor" href="#how-do-i-install-sourceanalytix-and-create-an-instance" aria-label="Permalink to &quot;How do I install SourceAnalytix and create an instance?&quot;">​</a></h2><p><strong>In short:</strong> In the ioBroker system settings, switch the repository to &quot;latest&quot; (beta) and install SourceAnalytix on the &quot;Adapters&quot; tab. Admin creates the instance <code>sourceanalytix.0</code> for you. Then open the instance settings and set up your first source on the &quot;Overview&quot; tab.</p><p>At the moment SourceAnalytix is only available in the &quot;latest&quot; repository, not in &quot;stable&quot;. It moves to &quot;stable&quot; after a test phase. With &quot;stable&quot; selected, you won&#39;t find it in the adapter list.</p><h3 id="how-to-do-it-from-v0-7-0" tabindex="-1">How to do it (from v0.7.0) <a class="header-anchor" href="#how-to-do-it-from-v0-7-0" aria-label="Permalink to &quot;How to do it (from v0.7.0)&quot;">​</a></h3><ol><li>Check the <a href="#requirements-sourceanalytix-have-node-js">requirements</a>, especially Admin 8.</li><li>In Admin, open the system settings and select the &quot;latest&quot; (beta) repository under &quot;Repositories&quot; as the active repository.</li><li>Open the &quot;Adapters&quot; tab, refresh the adapter list and search for &quot;SourceAnalytix&quot;.</li><li>Install the adapter. Admin creates the instance <code>sourceanalytix.0</code> and starts it.</li><li>On the &quot;Instances&quot; tab, open the settings of <code>sourceanalytix.0</code>. The &quot;Overview&quot; tab shows the &quot;Set up SourceAnalytix&quot; card with the steps &quot;Create a price&quot;, &quot;Add a source&quot; and &quot;View the values&quot;.</li><li>On the &quot;Price definitions&quot; tab, create at least one price definition, for example for electricity in kWh, and save. Saving restarts the adapter.</li><li>On the &quot;Overview&quot; tab, click &quot;Add first source&quot;. For what to do next, see <a href="./erster-zaehler#configure-sourceanalytix-datapoint">Where do I configure SourceAnalytix for a datapoint?</a>.</li></ol><p><img src="'+s+'" alt="The &quot;Overview&quot; tab right after installation, with the &quot;Set up SourceAnalytix&quot; card"></p><p>The &quot;Overview&quot; and &quot;Problems&quot; tabs need a running instance. If it is stopped, &quot;Instance is not running&quot; appears at the top with a &quot;Start&quot; button. All actions marked with ⚡ are locked until then.</p><h3 id="there-is-no-instance" tabindex="-1">There is no instance <a class="header-anchor" href="#there-is-no-instance" aria-label="Permalink to &quot;There is no instance&quot;">​</a></h3><p>If you installed SourceAnalytix from the console with npm or from a GitHub URL, ioBroker doesn&#39;t create an instance. Create it yourself with the plus icon, which adds an instance in Admin. One instance is enough for all sources.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Installing from a GitHub URL is only meant for testing, when the developer asks for it. Admin doesn&#39;t show updates for such an installation. To get back to the &quot;latest&quot; repository, see <a href="./../anleitungen/betrieb-und-wartung#update-sourceanalytix-downgrade">How do I update SourceAnalytix (and what is a downgrade)?</a>.</p></div><p><strong>Up to v0.6.x:</strong> The instance settings only contain &quot;Main settings&quot; and &quot;Price definitions&quot;. You enable sources there, on the datapoint on the &quot;Objects&quot; tab, with the wrench icon.</p><p><strong>See also:</strong> <a href="#need-several-instances-versions-side">Do I need several instances or versions side by side?</a> · <a href="./erster-zaehler#configure-sourceanalytix-datapoint">My first meter</a></p><p><a id="need-several-instances-versions-side"></a></p><h2 id="do-i-need-several-instances-or-versions-side-by-side" tabindex="-1">Do I need several instances or versions side by side? <a class="header-anchor" href="#do-i-need-several-instances-or-versions-side-by-side" aria-label="Permalink to &quot;Do I need several instances or versions side by side?&quot;">​</a></h2><p><strong>In short:</strong> No. One instance handles any number of sources, each with its own settings. You can&#39;t run two versions of SourceAnalytix side by side, because ioBroker installs exactly one version of each adapter.</p><h3 id="one-instance-for-everything" tabindex="-1">One instance for everything <a class="header-anchor" href="#one-instance-for-everything" aria-label="Permalink to &quot;One instance for everything&quot;">​</a></h3><p>The settings of a source apply per instance. They are stored on the datapoint under <code>common.custom.sourceanalytix.&lt;instance&gt;</code>, and each instance only calculates the sources that are enabled for it. The &quot;Overview&quot; and &quot;Problems&quot; tabs also show only the sources of that instance. A second instance gains you nothing, unless you deliberately want separate folders <code>sourceanalytix.0</code> and <code>sourceanalytix.1</code>.</p><p>Multiple instances always run the same installed version. So you can&#39;t test a new version next to the old one. Install it as an update after making a backup. To go back if something goes wrong, see <a href="./../anleitungen/betrieb-und-wartung#update-sourceanalytix-downgrade">Downgrade</a>.</p><h3 id="removing-an-extra-instance" tabindex="-1">Removing an extra instance <a class="header-anchor" href="#removing-an-extra-instance" aria-label="Permalink to &quot;Removing an extra instance&quot;">​</a></h3><p>A second instance often appears unnoticed, for example when you install SourceAnalytix from the repository again after a GitHub installation. To clean up:</p><ol><li>On the &quot;Objects&quot; tab, check which instance holds your values, that is, whether your folders are under <code>sourceanalytix.0</code> or under <code>sourceanalytix.1</code>.</li><li>On the &quot;Instances&quot; tab, delete the extra instance with the trash icon.</li></ol><div class="caution custom-block github-alert"><p class="custom-block-title">CAUTION</p><p>Deleting an instance also removes its folders with all values. Never delete the instance that holds your data. If you only want to retire a single source, use the &quot;Deactivate&quot; action on that source.</p></div><p><strong>See also:</strong> <a href="./../anleitungen/betrieb-und-wartung#disable-datapoint-remove-sources-states">Disable a datapoint or remove sources</a></p>',33)])])}const m=t(r,[["render",i]]);export{q as __pageData,m as default};
